<script setup lang="ts">
import {useV15CreateIntentPage} from '../../stores/useV15CreateIntentPage';
const {prefs,id,trip,categories,loading,busy,error,done,itemName,itemSpec,quantity,unit,categoryId,unitPrice,note,contactName,contactPhone,address,expectDate,insurance,unitLabels,unitIndex,goodsAmount,load,submit,unitChange,categoryChange,formatAmount,mobilePreferenceStyle} = useV15CreateIntentPage();
</script>
<template><scroll-view scroll-y class="original-subpage" :class="{'kx-dark':prefs.theme==='dark','kx-care':prefs.care}" :style="mobilePreferenceStyle(prefs)"><text class="op-back" @click="uni.navigateBack()">‹ {{$t('m2.mobile.back')}}</text><view class="op-title">{{$t('v15.createIntent')}}</view>
<view v-if="loading" class="op-empty">{{$t('account.loading')}}</view><view v-else-if="error&&!trip" class="op-error">{{error}}<button class="op-action op-secondary" @click="load">{{$t('common.retry')}}</button></view>
<template v-else-if="trip"><view class="op-card"><view class="op-card-title">{{$t('v15.tripInfo')}}</view><view class="op-row"><text>{{trip.destination}}</text><text>{{trip.depart_date||''}}</text></view></view>
<view class="op-card"><text class="v15-label">{{$t('v15.itemName')}} *</text><input class="v15-field" v-model="itemName" maxlength="120"/><text class="v15-label">{{$t('v15.itemSpec')}}</text><input class="v15-field" v-model="itemSpec" maxlength="160"/>
<view class="v15-flow-row"><view><text class="v15-label">{{$t('v15.quantity')}} *</text><input class="v15-field" type="number" v-model="quantity"/></view><view><text class="v15-label">{{$t('v15.unit')}}</text><picker :range="unitLabels.map(k=>$t(k))" :value="unitIndex" @change="unitChange"><view class="v15-selector">{{$t(unitLabels[unitIndex])}} ⌄</view></picker></view></view>
<text class="v15-label">{{$t('v15.category')}}</text><picker v-if="categories.length" :range="categories.map(c=>c.name)" :value="Math.max(0,categories.findIndex(c=>String(c.id)===categoryId))" @change="categoryChange"><view class="v15-selector">{{categories.find(c=>String(c.id)===categoryId)?.name||$t('v15.category')}} ⌄</view></picker>
<text class="v15-label">{{$t('v15.unitPrice')}} *</text><input class="v15-field" type="digit" v-model="unitPrice"/><text class="v15-label">{{$t('v15.note')}}</text><textarea class="v15-area" v-model="note" maxlength="3000"/>
<text class="v15-label">{{$t('v15.expectDate')}}</text><picker mode="date" @change="expectDate=String($event.detail.value)"><view class="v15-selector">{{expectDate||$t('v15.expectDate')}} ⌄</view></picker></view>
<view class="op-card"><text class="v15-section">{{$t('v15.receiver')}}</text><text class="v15-label">{{$t('v15.receiver')}} *</text><input class="v15-field" v-model="contactName" maxlength="80"/><text class="v15-label">{{$t('v15.phoneContact')}} *</text><input class="v15-field" v-model="contactPhone" maxlength="24"/><text class="v15-label">{{$t('v15.address')}} *</text><textarea class="v15-area" v-model="address" maxlength="500"/></view>
<view class="op-card"><text class="v15-section">{{$t('v15.insurance')}}</text><view class="v15-choices"><view class="v15-choice" :class="{selected:insurance==='yes'}" @click="insurance='yes'">{{$t('v15.insure')}}</view><view class="v15-choice" :class="{selected:insurance==='waived'}" @click="insurance='waived'">{{$t('v15.waive')}}</view></view><view class="op-row"><text>{{$t('v15.amount')}}</text><text>{{Number.isFinite(goodsAmount)?formatAmount(goodsAmount):'—'}}</text></view><view class="op-muted">{{$t('v15.intentPostUnavailable')}}</view><button class="op-action" :disabled="busy||!!done" @click="submit">{{$t('v15.submit')}}</button></view>
<view v-if="done" class="op-banner" @click="uni.navigateTo({url:'/pages/intent-detail/index?id='+encodeURIComponent(done)})">{{$t('v15.intentCreated')}} · {{done}} ›</view><view v-if="error" class="op-error">{{error}}</view>
</template></scroll-view></template>
